import { OP_TARGETS, TARGETS } from "@/app-services/validator/targets";
import { examplesFor } from "@/app-services/validator/examples";
import { SCOPE_NOTE } from "@/app-services/validator/validate";
import { UCP_VERSION } from "@/ucp/constants";

/** Validation targets with a valid and several invalid example each. Examples are generated by the project's own code and verified by tests. */
export async function GET() {
  return Response.json({
    ucpVersion: UCP_VERSION,
    scope: SCOPE_NOTE,
    opTargets: OP_TARGETS,
    targets: TARGETS.map((t) => ({ id: t.id, label: t.label, direction: t.direction, description: t.description, zodName: t.zodName, docFile: t.docFile, docUrl: t.docUrl, hasRules: Boolean(t.rules), examples: examplesFor(t.id) })),
  });
}
